'use strict';

const fs = require('fs');
const path = require('path');

/** Height of the custom title bar (the traffic lights / overlay buttons sit in it). */
const TITLEBAR_HEIGHT = 36;

/** Logo with mark and wordmark; the wordmark uses currentColor. Generated by branding/build_logo.py. */
const LOGO_SVG = fs.readFileSync(path.join(__dirname, '..', 'assets', 'logo.svg'), 'utf8').trim();

const LIGHT_CHROME = { color: '#f0f2f6', symbolColor: '#31333f' };
const DARK_CHROME = { color: '#262730', symbolColor: '#fafafa' };
const LIGHT_CONTENT = '#ffffff';
const DARK_CONTENT = '#0e1117';

const DATA_URL_PREFIX = 'data:text/html;charset=utf-8,';

/**
 * Title bar colours, based on Streamlit's default themes.
 * @param {boolean} dark
 * @returns {{ color: string, symbolColor: string }}
 */
function chromeColors(dark) {
  return { ...(dark ? DARK_CHROME : LIGHT_CHROME) };
}

/**
 * @param {boolean} dark
 * @returns {'#ffffff' | '#0e1117'}
 */
function contentBackground(dark) {
  return dark ? DARK_CONTENT : LIGHT_CONTENT;
}

function escapeHtml(text) {
  return String(text).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[c]);
}

/**
 * A data: URL with a draggable title bar and an optional text below it. The colours follow
 * prefers-color-scheme. Used by the loading window and the main window.
 * @param {{ title: string, lang?: string, text?: string }} options
 * @returns {string}
 */
function barPage({ title, lang = 'en', text = '' }) {
  const light = chromeColors(false);
  const dark = chromeColors(true);
  const html =
    '<!doctype html><html lang="' + escapeHtml(lang) + '"><head><meta charset="utf-8">' +
    '<title>' + escapeHtml(title) + '</title><style>' +
    ':root{--bar:' + light.color + ';--bar-ink:' + light.symbolColor +
    ';--content:' + contentBackground(false) + ';--ink:' + light.symbolColor + '}' +
    '@media (prefers-color-scheme: dark){:root{--bar:' + dark.color + ';--bar-ink:' + dark.symbolColor +
    ';--content:' + contentBackground(true) + ';--ink:' + dark.symbolColor + '}}' +
    'html,body{margin:0;height:100%}' +
    'body{display:flex;flex-direction:column;font-family:system-ui,sans-serif;background:var(--content);color:var(--ink)}' +
    '.bar{flex:none;height:' + TITLEBAR_HEIGHT + 'px;display:flex;align-items:center;justify-content:center;' +
    'background:var(--bar);color:var(--bar-ink);font-size:13px;-webkit-app-region:drag;user-select:none}' +
    '.bar svg{height:18px;width:auto}' +
    '.main{flex:1;display:flex;align-items:center;justify-content:center}' +
    'p{margin:0 24px;text-align:center;font-size:15px}' +
    '</style></head><body><header class="bar">' + LOGO_SVG + '</header>' +
    '<div class="main"><p>' + escapeHtml(text) + '</p></div></body></html>';
  return DATA_URL_PREFIX + encodeURIComponent(html);
}

/**
 * BrowserWindow options for the hidden title bar. macOS keeps the traffic lights,
 * elsewhere the window controls are drawn as an overlay.
 * @param {string} platform process.platform
 * @param {boolean} dark
 * @returns {object}
 */
function titleBarOptions(platform, dark) {
  if (platform === 'darwin') {
    return { titleBarStyle: 'hidden', trafficLightPosition: { x: 16, y: 11 } };
  }
  return { titleBarStyle: 'hidden', titleBarOverlay: { ...chromeColors(dark), height: TITLEBAR_HEIGHT } };
}

module.exports = { TITLEBAR_HEIGHT, chromeColors, contentBackground, barPage, titleBarOptions };
